export default function MaximilianKolbe({
  p,
  detail,
}: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        {/* Stable white paper underneath every paint region. */}
        <rect
          x="0"
          y="0"
          width="1086"
          height="1448"
          fill={PAPER}
          pointerEvents="none"
        />

        {/* Open sky background behind the saint. */}
        <g {...p('background')} stroke="none">
          <rect x="0" y="0" width="1086" height="1448" />
        </g>

        {/* Left and right cloud banks. */}
        <g {...p('cloud')} stroke="none">
          <path d={CLOUD_MASK} />
        </g>

        {/* Halo field behind the head, including the radiant circular backdrop. */}
        <g {...p('halo')} stroke="none">
          <path d={HALO_MASK} />
        </g>

        {/* Hood, outer drape, and sleeve forms of the habit. */}
        <g {...p('mantle')} stroke="none">
          <path d={MANTLE_MASK} />
        </g>

        {/* Inner habit / robe body and lower garment. */}
        <g {...p('robe')} stroke="none">
          <path d={ROBE_MASK} />
        </g>

        {/* Face, ears, neck, and both hands. */}
        <g {...p('skin')} stroke="none">
          <path d={SKIN_MASK} />
        </g>

        {/* Close-cropped hair and brows. */}
        <g {...p('hair')} stroke="none">
          <path d={HAIR_MASK} />
        </g>

        {/* Rosary, crucifix, rope cincture, glasses, and pedestal accents. */}
        <g {...p('accent')} stroke="none">
          <path d={ACCENT_MASK} />
        </g>

        {/* Marian statue, chest emblem, and surrounding star symbols. */}
        <g {...p('symbol')} stroke="none">
          <path d={SYMBOL_MASK} />
        </g>

        {/* Exact traced black line art from the supplied Maximilian Kolbe image.
            Keep this last and non-interactive so every region remains paintable. */}
        <path
          {...detail}
          {...ink}
          d={MAXIMILIAN_KOLBE_LINE_ART}
          fill={STROKE}
          stroke="none"
          fillRule="evenodd"
          pointerEvents="none"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}